import Foundation
import XCTest
@testable import FiestaBoardRender

/// The LED raster against FiestaUI's goldens (`Fixtures/shared/led-golden.json`,
/// generated by `scripts/ci/led-fixtures.mjs`): every layout case must draw
/// byte-identical RGB888 frames — 0 differing pixels.
final class LedGoldenTests: XCTestCase {

    struct Case {
        let name: String
        let json: [String: Any]
        var message: String { json["message"] as? String ?? "" }
        var spec: [String: Any] { json["spec"] as? [String: Any] ?? [:] }
        var options: [String: Any] { json["options"] as? [String: Any] ?? [:] }
        var width: Int { spec["width"] as? Int ?? 0 }
        var height: Int { spec["height"] as? Int ?? 0 }
        var font: String { spec["font"] as? String ?? "5x7" }
        var expected: [UInt8] { [UInt8](Data(base64Encoded: json["frame"] as? String ?? "") ?? Data()) }
        var mixedCase: Bool { options["letterCase"] as? String == "mixed" }
        var layers: [PixelLayer] {
            (options["layers"] as? [[String: Any]] ?? []).map { layer in
                PixelLayer(x: layer["x"] as? Int ?? 0, y: layer["y"] as? Int ?? 0,
                           w: layer["width"] as? Int ?? 0, h: layer["height"] as? Int ?? 0,
                           rgba: Data(base64Encoded: layer["rgba"] as? String ?? "") ?? Data())
            }
        }
        var ledOptions: LedRasterizer.Options {
            var o = LedRasterizer.Options()
            o.textColor = options["textColor"] as? String
            o.monochrome = options["monochrome"] as? String
            o.mixedCase = mixedCase
            o.tileGapFill = options["tileGap"] as? String == "fill"
            o.blockPadding = options["blockPadding"] as? Int ?? 0
            o.glyphs = (json["charset"] as? [String: Any])?["glyphs"] as? [String: [String]]
            return o
        }
        /// `cells` as the LED path's tokens, spelled exactly as given.
        var cellRows: [[LedToken]]? {
            (json["cells"] as? [[[String: Any]]])?.map { row in
                row.map { cell in
                    var token: LedToken = cell["type"] as? String == "color"
                        ? .tile(cell["code"] as? String ?? "") : .char(cell["value"] as? String ?? " ")
                    token.color = cell["color"] as? String
                    token.background = cell["background"] as? String
                    token.icon = cell["icon"] as? String
                    return token
                }
            }
        }
    }

    nonisolated(unsafe) static let golden: [String: Any] = {
        let root = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent()
        let url = root.appendingPathComponent("Fixtures/shared/led-golden.json")
        guard let data = try? Data(contentsOf: url),
              let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return [:] }
        return json
    }()

    nonisolated(unsafe) static let cases: [Case] = (golden["layouts"] as? [[String: Any]] ?? []).map {
        Case(name: $0["name"] as? String ?? "?", json: $0)
    }

    static func differingPixels(_ raster: MatrixRaster, _ expected: [UInt8]) -> Int {
        guard raster.rgb.count == expected.count else { return max(raster.width * raster.height, expected.count / 3) }
        var count = 0
        for p in 0..<(expected.count / 3) {
            let i = p * 3
            if raster.rgb[i] != expected[i] || raster.rgb[i + 1] != expected[i + 1] || raster.rgb[i + 2] != expected[i + 2] {
                count += 1
            }
        }
        return count
    }

    static func render(_ c: Case) -> MatrixRaster {
        if let rows = c.cellRows {
            return LedRasterizer.render(rows: rows, width: c.width, height: c.height, font: c.font,
                                        options: c.ledOptions, layers: c.layers)
        }
        return LedRasterizer.render(message: c.message, width: c.width, height: c.height, font: c.font,
                                    options: c.ledOptions, layers: c.layers)
    }

    func named(_ name: String) throws -> Case {
        try XCTUnwrap(Self.cases.first { $0.name == name }, "no golden case \(name)")
    }

    func assertMatches(_ name: String, file: StaticString = #filePath, line: UInt = #line) throws {
        let c = try named(name)
        XCTAssertEqual(Self.differingPixels(Self.render(c), c.expected), 0, name, file: file, line: line)
    }

    // MARK: Every case

    func testGoldenFileLoads() {
        XCTAssertEqual(Self.cases.count, 30, "led-golden.json layouts")
    }

    func testEveryLayoutCaseMatchesGolden() {
        XCTAssertFalse(Self.cases.isEmpty)
        var failures: [String] = []
        for c in Self.cases {
            let diff = Self.differingPixels(Self.render(c), c.expected)
            if diff != 0 { failures.append("\(c.name): \(diff) px differ") }
        }
        XCTAssert(failures.isEmpty, "\(failures.count)/\(Self.cases.count) golden cases differ:\n" + failures.joined(separator: "\n"))
    }

    /// A cells-in case draws the same frame as its message (`layoutLedCellGrid` ≡ `layoutLedMessage`).
    func testCellsCaseDrawsTheSameFrameAsItsMessage() throws {
        for c in Self.cases where c.cellRows != nil {
            let fromCells = Self.render(c)
            let fromMessage = LedRasterizer.render(message: c.message, width: c.width, height: c.height, font: c.font,
                                                   options: c.ledOptions, layers: c.layers)
            XCTAssertEqual(fromCells, fromMessage, c.name)
        }
    }

    /// The app's entry point — `raster(_:model:)` with a `DisplayModel` decoded
    /// from a `device_model_spec` and `led_layout` — draws the golden frames too,
    /// for every case it can express (no plugin set, no text colour).
    func testPublicRasterMatchesGolden() {
        var failures: [String] = []
        var checked = 0
        for c in Self.cases where c.json["charset"] == nil && c.options["textColor"] == nil {
            var spec: [String: Any] = ["technology": "led_matrix", "font": c.font,
                                       "geometry": ["width": c.width, "height": c.height]]
            if let mono = c.options["monochrome"] as? String { spec["color"] = ["kind": "monochrome", "color": mono] }
            let stored: [String: Any] = [
                "device_model_spec": spec,
                "led_layout": ["tile_gap": c.options["tileGap"] as? String ?? "gap",
                               "block_padding": c.options["blockPadding"] as? Int ?? 0],
            ]
            let model = DisplayModel(summary: BoardSummaryFields(deviceType: nil, rows: 0, cols: 0), stored: stored)
            let frame: BoardFrame
            if let cells = c.json["cells"] as? [[Any]] {
                let tokens = cells.map { $0.compactMap(BoardToken.init(json:)) }
                frame = BoardFrame(rows: model.rows, cols: model.cols, cells: tokens, layers: c.layers)
            } else {
                // The LED path keeps case; an upper-case case is its message upper-cased
                // (markup heads and icon names are case-insensitive).
                frame = BoardFrame(rows: model.rows, cols: model.cols,
                                   message: c.mixedCase ? c.message : c.message.uppercased(), layers: c.layers)
            }
            checked += 1
            let diff = Self.differingPixels(LedRasterizer.raster(frame, model: model), c.expected)
            if diff != 0 { failures.append("\(c.name): \(diff) px differ") }
        }
        XCTAssertGreaterThanOrEqual(checked, 28)
        XCTAssert(failures.isEmpty, failures.joined(separator: "\n"))
    }

    // MARK: Named cases

    func testLayersOverTextAlphaAndClipping() throws { try assertMatches("bitmap layers over text, alpha and clipping") }
    func testLayerOnMonochromePanel() throws { try assertMatches("bitmap layer on a monochrome red panel") }
    func testAwtrixClip() throws { try assertMatches("awtrix 3x5 clip") }
    func testWeatherWithTiles() throws { try assertMatches("5x7 weather with tiles") }
    func testSpansBlockIconLowercase() throws { try assertMatches("spans, block, icon, lowercase") }
    func testMonochromeAmberWithBlock() throws { try assertMatches("monochrome amber with block") }
    func testDegreeAndTypedHearts() throws { try assertMatches("degree and typed hearts") }
    func testIconAliasesAndFallbacks() throws { try assertMatches("icon aliases and fallbacks") }
    func testPluginGlyphOverridesFace() throws { try assertMatches("plugin glyph overrides the face's") }
    func testPluginSetMonochrome() throws { try assertMatches("plugin set with custom glyph, monochrome") }
    func testFillMergesSameColourTiles() throws {
        try assertMatches("fill: tiles merge horizontally, vertically and at a four-way corner; other colours stay apart")
    }
    func testFillLShapeCornerUnlit() throws { try assertMatches("fill: an L of three tiles leaves the corner pixel unlit") }
    func testPaddingClippedAtEdge() throws { try assertMatches("padding: a block at the matrix edge is clipped at the edge") }
    func testPaddingAdjacentDifferentColours() throws {
        try assertMatches("padding: two adjacent padded blocks of different colours keep an unlit line between them")
    }
    func testMonochromeFillAndPadding() throws {
        try assertMatches("monochrome amber: fill and padding merge every field, inverse glyphs stay crisp")
    }
    func testPixooFillAndPadding() throws { try assertMatches("pixoo 3x5 with fill and padding") }
    func testCellsInFillAndPadding() throws { try assertMatches("cells-in with fill and padding") }
}
